#!/bin/bash
# ==============================================================================
# JTG THEME INSTALLER FOR PTERODACTYL PANEL
# Design: Void Black, Glassmorphism, Chakra Petch & Outfit Fonts
# 100% Compatible with Blueprint Extensions
# ==============================================================================

# Ensure script is run as root
if [ "$EUID" -ne 0 ]; then
  echo -e "\e[31m[!] Please run this script as root (sudo bash ...)\e[0m"
  exit 1
fi

PANEL_DIR="/var/www/pterodactyl"
if [ ! -d "$PANEL_DIR" ]; then
  echo -e "\e[31m[!] Pterodactyl directory not found at $PANEL_DIR\e[0m"
  exit 1
fi

cd "$PANEL_DIR" || exit 1

prompt() {
  if [ -t 0 ]; then
    read -rp "$1" "$2"
  else
    read -rp "$1" "$2" < /dev/tty
  fi
}

WRAPPER_FILE="$PANEL_DIR/resources/views/templates/wrapper.blade.php"
THEME_DIR="$PANEL_DIR/public/themes/jtg"
THEME_CSS="$THEME_DIR/theme-v2.css"

deploy_theme_files() {
  echo "[*] Creating theme directory..."
  mkdir -p "$THEME_DIR"

  echo "[*] Deploying fresh JTG Theme CSS (bypassing Cloudflare cache)..."
  base64 -d << 'EOF_CSS' > "$THEME_CSS"

EOF_CSS

  # Also write theme.css for fallback
  cp -f "$THEME_CSS" "$THEME_DIR/theme.css"

  # Inject or update wrapper.blade.php
  if [ -f "$WRAPPER_FILE" ]; then
    if [ ! -f "$WRAPPER_FILE.jtg-bak" ]; then
      cp -a "$WRAPPER_FILE" "$WRAPPER_FILE.jtg-bak"
    fi

    # Clean any old theme tags
    sed -i '/JTG THEME/d' "$WRAPPER_FILE" 2>/dev/null || true
    sed -i '/themes\/jtg\/theme/d' "$WRAPPER_FILE" 2>/dev/null || true

    echo "[*] Injecting theme-v2.css into wrapper.blade.php..."
    sed -i 's|</head>|    <!-- JTG THEME -->\n    <link rel="stylesheet" href="/themes/jtg/theme-v2.css">\n</head>|g' "$WRAPPER_FILE"
  fi
}

rebuild_and_optimize() {
  echo "[*] Purging compiled view and config cache..."
  rm -f "$PANEL_DIR/storage/framework/views/"*.php 2>/dev/null || true
  php artisan view:clear >/dev/null 2>&1 || true
  php artisan config:clear >/dev/null 2>&1 || true
  chmod -R 755 storage/* bootstrap/cache 2>/dev/null || true

  # Rebuild Blueprint if command exists
  if command -v blueprint >/dev/null 2>&1; then
    echo -e "\e[36m[*] Blueprint framework detected. Verifying extension compatibility...\e[0m"
    blueprint -b 2>/dev/null || true
  fi

  echo "[*] Setting file permissions..."
  chown -R www-data:www-data "$PANEL_DIR"/* 2>/dev/null || true
  php artisan queue:restart >/dev/null 2>&1 || true
}

clear
echo -e "\e[36m=====================================================\e[0m"
echo -e "\e[37;1m           JTG THEME FOR PTERODACTYL PANEL           \e[0m"
echo -e "\e[36m=====================================================\e[0m"
echo -e " 1) \e[32mInstall JTG Theme\e[0m  (Auth Screens + Inside Dashboard)"
echo -e " 2) \e[33mUpdate JTG Theme\e[0m   (Deploy v2 & purge cache)"
echo -e " 3) \e[31mRemove JTG Theme\e[0m   (Restore default Pterodactyl)"
echo -e " 4) Exit"
echo -e "\e[36m=====================================================\e[0m"
prompt "Select an option [1-4]: " OPTION

case $OPTION in
  1)
    echo -e "\n\e[32m--- Installing JTG Theme ---\e[0m"
    php artisan down 2>/dev/null || true
    deploy_theme_files
    rebuild_and_optimize
    php artisan up 2>/dev/null || true
    echo -e "\n\e[32m[✓] JTG Theme installed successfully!\e[0m"
    echo -e "\e[36mTip: Refresh your browser to view the updated theme.\e[0m"
    ;;

  2)
    echo -e "\n\e[33m--- Updating JTG Theme ---\e[0m"
    php artisan down 2>/dev/null || true
    deploy_theme_files
    rebuild_and_optimize
    php artisan up 2>/dev/null || true
    echo -e "\n\e[32m[✓] JTG Theme updated successfully!\e[0m"
    ;;

  3)
    echo -e "\n\e[31m--- Removing JTG Theme ---\e[0m"
    prompt "Are you sure you want to revert to default Pterodactyl? [y/N]: " CONFIRM
    if [[ "$CONFIRM" =~ ^[Yy]$ ]]; then
      php artisan down 2>/dev/null || true
      if [ -f "$WRAPPER_FILE.jtg-bak" ]; then
        echo "[*] Restoring original wrapper.blade.php..."
        mv -f "$WRAPPER_FILE.jtg-bak" "$WRAPPER_FILE"
      else
        sed -i '/JTG THEME/d' "$WRAPPER_FILE" 2>/dev/null || true
        sed -i '/themes\/jtg\/theme/d' "$WRAPPER_FILE" 2>/dev/null || true
      fi
      rm -rf "$THEME_DIR"
      rebuild_and_optimize
      php artisan up 2>/dev/null || true
      echo -e "\n\e[32m[✓] JTG Theme removed. Default panel restored!\e[0m"
    else
      echo "Cancelled."
    fi
    ;;

  4)
    echo "Exiting."
    exit 0
    ;;

  *)
    echo -e "\e[31mInvalid option.\e[0m"
    exit 1
    ;;
esac
